            selected_candidate = next((record for record in post if record['index'] > candidate['index'] and record.get('status') == 200 and record.get('attributeName') == 'selected' and record.get('selectedValue') is True and record.get('elementSha256') == element and successful_execution(record,executions)),None)
            label_candidate = next((record for record in post if record['index'] > candidate['index'] and record.get('status') == 200 and record.get('elementSha256') == element and 'targetName' in record.get('responseMatches',[]) and successful_execution(record,executions)),None)
            folder_candidate = next((record for record in post if record['index'] >= epoch['index'] and record.get('status') == 200 and ('targetFolderName' in record.get('responseMatches',[]) or 'targetDir' in record.get('responseMatches',[]) or 'targetUri' in record.get('responseMatches',[])) and _owned_window_for_element(identity,record.get('elementSha256'),target_title,epoch['index'])[0] is not None and successful_execution(record,executions)),None)
            if selected_candidate is None or label_candidate is None or folder_candidate is None:
