        checks['noRetypeOrResaveAfterInterrupt'] = not any(_is_typing(record,marker) or 'save' in record.get('gestures',[]) or 'saveAs' in record.get('gestures',[]) for record in after_interrupt)
        checks['twoOwnedSessions'] = len(creates) == 2
    if scenario == 'M7':
        _, parent = window_epochs(records)
        fault = next((item for item in controls if item.get('action') == 'stop-server' and item.get('succeeded')),None)
        creates = _create_records(records)
        single_session = creates[0].get('sessionCreatedSha256') if len(creates) == 1 else None
        pre = [record for record in records if fault and _utc(record.get('startedAt')) and _utc(fault.get('completedAt')) and _utc(record['startedAt']) < _utc(fault['completedAt'])]
        typing = next((record for record in pre if single_session and record.get('sessionSha256') == single_session and _is_typing(record,marker) and successful_execution(record,executions)),None)
        identity = _target_window_observations(records,parent,single_session,'initialTargetText',executions,title_before_index=typing['index'],before_index=typing['index']) if typing and single_session else []
        identity_windows = {item['window'] for item in identity}
        save = next((record for record in pre if typing and record.get('sessionSha256') == single_session and record['index'] > typing['index'] and _is_save(record) and successful_execution(record,executions)),None)
        pre_indices = {record['index'] for record in pre}
