        if save and single_session:
            saved = next((item['record'] for item in _target_window_observations(records,parent,single_session,'marker',executions,after_index=save['index']) if item['window'] in identity_windows and item['record']['index'] in pre_indices),None)
        post = [execution for execution in (executions or []) if fault and _after(execution['window'][0].isoformat(),fault.get('completedAt'))]
        failed = [execution for execution in post if execution['status'] == 'failed' and execution['kernelState'] == 'alive' and str(execution.get('errorType','')).rsplit('.',1)[-1] in NETWORK_ERROR_TYPES]
        successes = [execution for execution in post if execution['status'] == 'completed' and execution['success'] is True]
        payload_map = _execution_payloads(executions or [],native,payloads or [])
        quit_attempt = None
        if len(failed) == 1 and post and failed[0] is post[-1]:
            candidate = failed[0]
            payload = payload_map.get(candidate['index']) if payload_map else None
            facts = _quit_failure_facts(payload,fault.get('ownedSessionSha256'))
            native['quitFailureEvidence'] = dict(facts,executionCount=candidate['executionCount'],callSha256=candidate.get('callSha256'))
            if facts['quitFrameObserved'] and facts['ownedRootSessionUrlObserved']:
